SELECT id,pid,phase_id,name,type,plan_start_time,plan_end_time,priority,status,
charge_name,quote_sys_task_id,product_id,charge_id,process_id FROM project_task
WHERE product_id=#{productId} 

    AND phase_id=#{phaseId}


    ${param}


    AND name LIKE concat('%',#{searchKeyword},'%')


    AND charge_id =#{userId}


    AND status IN

        #{state}






                AND name LIKE concat('%',#{item.searchKeyword},'%')




                AND priority =#{item.priority}




                AND charge_id =#{item.chargeId}




                AND status =#{item.status}




                AND create_time >=#{item.startTime}


                AND end_time >=#{item.endTime}






ORDER BY
create_time ASC

